package net.officefloor.hq.app.user;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The signed-in user's own locale, kept per user across every sheet. */
@RestController
@RequestMapping("/api/me/locale")
@Validated
public class UserPrefController {

    public record LocaleChange(@NotBlank @Size(max = 10) String locale) {
    }

    public record LocaleView(String locale) {
    }

    private final UserPrefService service;

    public UserPrefController(UserPrefService service) {
        this.service = service;
    }

    @GetMapping
    public LocaleView get(@RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return new LocaleView(service.localeOf(user.trim()));
    }

    @PutMapping
    public LocaleView set(@RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody LocaleChange request) {
        return new LocaleView(service.setLocale(user.trim(), request.locale().trim()));
    }
}
package net.officefloor.hq.app.user;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A user's own preferences, kept across every sheet. */
@Entity
@Table(name = "user_pref")
public class UserPref {

    @Id
    @Column(name = "user_name", nullable = false)
    private String user;

    /** How the screen shows this user figures: en (1234.56) or de (1.234,56). */
    @Column(name = "locale", nullable = false)
    private String locale;

    protected UserPref() {
    }

    public UserPref(String user, String locale) {
        this.user = user;
        this.locale = locale;
    }

    public String getUser() {
        return user;
    }

    public String getLocale() {
        return locale;
    }

    public void setLocale(String locale) {
        this.locale = locale;
    }
}
package net.officefloor.hq.app.user;

import org.springframework.data.jpa.repository.JpaRepository;

public interface UserPrefRepository extends JpaRepository<UserPref, String> {
}
package net.officefloor.hq.app.user;

import java.util.Set;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** A user's locale: en unless chosen. Choosing one writes no audit line. */
@Service
public class UserPrefService {

    public static final String DEFAULT_LOCALE = "en";

    public static final Set<String> LOCALES = Set.of("en", "de");

    private final UserPrefRepository prefs;

    public UserPrefService(UserPrefRepository prefs) {
        this.prefs = prefs;
    }

    @Transactional(readOnly = true)
    public String localeOf(String user) {
        return prefs.findById(user).map(UserPref::getLocale).orElse(DEFAULT_LOCALE);
    }

    @Transactional
    public String setLocale(String user, String locale) {
        if (!LOCALES.contains(locale)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Choose en or de");
        }
        prefs.findById(user).ifPresentOrElse(p -> p.setLocale(locale), () -> prefs.save(new UserPref(user, locale)));
        return locale;
    }
}
package net.officefloor.hq.app.session;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import net.officefloor.hq.app.user.UserPrefService;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Sign-in by name only: there is no password. */
@RestController
@RequestMapping("/api/signin")
public class SessionController {

    public record SignIn(@NotBlank @Size(max = 100) String name) {
    }

    /** The name signed in with, and the locale the screen shows them figures in. */
    public record SignedIn(String name, String locale) {
    }

    private final UserPrefService prefs;

    public SessionController(UserPrefService prefs) {
        this.prefs = prefs;
    }

    @PostMapping
    public SignedIn signIn(@Valid @RequestBody SignIn request) {
        String name = request.name().trim();
        return new SignedIn(name, prefs.localeOf(name));
    }
}
